const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const centerPoint = ee.Geometry.Point(-73.845369, -9.799994);
    const radiusKm = 5;
    const geometry = centerPoint.buffer(radiusKm * 1000); // Buffer in meters

    const year2017 = 2017;
    const year2022 = 2022;

    // 2. Data Acquisition & Preprocessing
    // Hansen Global Forest Change v1.10 (2000-2022)
    const gfc = ee.Image('UMD/hansen/global_forest_change_v1_10');

    // Define forest based on treecover2000 (e.g., > 10% canopy closure)
    // And lossyear (0 for no loss, or year of loss as 1-22 for 2001-2022)
    const treeCoverThreshold = 10; // Percent canopy closure

    // Function to calculate forest area for a given year
    const calculateForestArea = (year) => {
      const yearCode = year - 2000;

      // Forest pixels are those with treecover2000 above threshold AND
      // lossyear is 0 (no loss) OR lossyear is after the target year.
      const forest = gfc.select('treecover2000').gt(treeCoverThreshold)
        .and(gfc.select('lossyear').eq(0).or(gfc.select('lossyear').gt(yearCode)));

      // Calculate pixel area for forest pixels
      // The resolution of Hansen data is approximately 30m. Let's use 30 for calculations.
      // Although we use a larger scale in reduceRegion for performance.
      const forestAreaImage = forest.multiply(ee.Image.pixelArea()).divide(10000); // Area in hectares

      // Reduce the image to get the sum of forest area within the geometry
      // Use a scale of 1000 or 3000 to avoid timeout for a 5km radius.
      // Maximum pixels for a 5km radius at 30m resolution is (10000/30)^2 * PI = 111111 * 3.14 = 348888.
      // So maxPixels=1e9 is fine.
      const stats = forestAreaImage.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: 30, // Hansen data is ~30m, use this for accurate area calculation
        maxPixels: 1e9,
        crs: 'EPSG:4326', // Use WGS84 as CRS
        bestEffort: true
      });

      return stats.get('treecover2000'); // The band name from the original image
    };

    // Calculate forest area for 2017
    const forestArea2017 = await calculateForestArea(year2017).getInfo();

    // Calculate forest area for 2022
    const forestArea2022 = await calculateForestArea(year2022).getInfo();

    // 3. Validation & Final Answer
    if (forestArea2017 === null || isNaN(forestArea2017)) {
      console.log("Calculation failed for 2017.");
      console.log("C3");
      return;
    }

    if (forestArea2022 === null || isNaN(forestArea2022)) {
      console.log("Calculation failed for 2022.");
      console.log("C3");
      return;
    }

    // Check if there are any valid pixels in the region at all
    // We can do this by checking a simple count of pixels in the geometry
    const pixelCount = gfc.select('treecover2000').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 30,
      maxPixels: 1e9,
      bestEffort: true
    }).get('treecover2000').getInfo();

    if (pixelCount === 0) {
      console.log("No valid pixels found in the specified region.");
      console.log("C2");
      return;
    }

    console.log(`Forest Area ${year2017}: ${forestArea2017.toFixed(2)} ha`);
    console.log(`Forest Area ${year2022}: ${forestArea2022.toFixed(2)} ha`);
    console.log(`Total pixels in region: ${pixelCount}`);

    if (forestArea2022 > forestArea2017) {
      console.log("A"); // Yes, area was larger in 2022
    } else {
      console.log("B"); // No, area was not larger in 2022
    }

  } catch (error) {
    console.log("An error occurred during the analysis:", error);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
